import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';

const RobotScene = () => {
    const mountRef = useRef(null);

    useEffect(() => {
        // --- SETUP SCÉNY ---
        const width = window.innerWidth;
        const height = window.innerHeight;

        const scene = new THREE.Scene();
        // Šedé pozadí pro debugování (ať vidíme kontrast)
        scene.background = new THREE.Color(0x222222); 

        const camera = new THREE.PerspectiveCamera(50, width / height, 0.1, 1000);
        camera.position.set(0, 1, 5); // Kamera kouká zepředu

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(width, height);
        
        const currentRef = mountRef.current;
        if (currentRef) {
            // Vyčistíme předchozí canvasy, pokud tam nějaké zůstaly
            while (currentRef.firstChild) {
                currentRef.removeChild(currentRef.firstChild);
            }
            currentRef.appendChild(renderer.domElement);
        }

        // --- POMOCNÍCI (DEBUG) ---
        // 1. Mřížka na podlaze (velikost 10, dílky po 1)
        const gridHelper = new THREE.GridHelper(10, 10);
        scene.add(gridHelper);

        // 2. Osy (Červená=X, Zelená=Y, Modrá=Z)
        const axesHelper = new THREE.AxesHelper(2);
        scene.add(axesHelper);

        // --- SVĚTLA ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 1);
        scene.add(ambientLight);
        const dirLight = new THREE.DirectionalLight(0xffffff, 2);
        dirLight.position.set(2, 2, 5);
        scene.add(dirLight);

        // --- MODEL ---
        let mixer;
        let headObject;
        const loader = new GLTFLoader();

        console.log("Začínám načítat model..."); // Kontrola v konzoli

        loader.load(
            '/Samurai.glb', 
            (gltf) => {
                console.log("Model úspěšně načten!", gltf);
                const model = gltf.scene;

                // Nastavíme bezpečnou velikost a pozici na střed
                model.scale.set(0.2, 0.2, 0.2); 
                model.position.set(0, 0, 0); 
                
                scene.add(model);

                // --- HLEDÁNÍ ČÁSTÍ ---
                // Vypíšeme všechny názvy objektů do konzole, abychom zkontrolovali jména
                const objectNames = [];
                model.traverse((child) => {
                    if (child.isMesh) objectNames.push(child.name);
                });
                console.log("Seznam objektů v modelu:", objectNames);

                const torso = model.getObjectByName('Torso');
                const head = model.getObjectByName('Head');

                if (torso && head) {
                    console.log("Nalezeno Torso i Head. Spojuji...");
                    torso.add(head);
                    // Reset pozice hlavy vůči tělu
                    head.position.set(0, 0, 0); 
                    head.rotation.set(0, 0, 0);
                    
                    // Pokud je hlava moc nízko, zvedni ji tady změnou Y:
                    // head.position.y = 0.5; 
                    
                    headObject = head;
                } else {
                    console.error("CHYBA: Nenašlo se Torso nebo Head! Zkontroluj výpis jmen výše.");
                }

                if (gltf.animations.length > 0) {
                    mixer = new THREE.AnimationMixer(model);
                    mixer.clipAction(gltf.animations[0]).play();
                }
            },
            // Progress callback
            (xhr) => {
                console.log((xhr.loaded / xhr.total * 100) + '% načteno');
            },
            // Error callback
            (error) => {
                console.error('CHYBA PŘI NAČÍTÁNÍ:', error);
            }
        );

        // --- UPDATE LOOP ---
        const mouse = new THREE.Vector2();
        const windowHalf = new THREE.Vector2(window.innerWidth / 2, window.innerHeight / 2);

        const handleMouseMove = (event) => {
            mouse.x = (event.clientX - windowHalf.x) / windowHalf.x;
            mouse.y = (event.clientY - windowHalf.y) / windowHalf.y;
        };
        document.addEventListener('mousemove', handleMouseMove);

        const clock = new THREE.Clock();
        let animationId;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            const delta = clock.getDelta();

            if (mixer) mixer.update(delta);

            if (headObject) {
                headObject.rotation.y = -mouse.x * 0.5;
                headObject.rotation.x = -mouse.y * 0.5;
            }

            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            document.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            if (currentRef) currentRef.removeChild(renderer.domElement);
            renderer.dispose();
        };
    }, []);

    return (
        <div 
            ref={mountRef} 
            style={{ 
                width: '100%', 
                height: '100vh',
                position: 'fixed', // Fixní pozice
                top: 0,
                left: 0,
                zIndex: 0 // Pod textem, ale viditelný
            }} 
        />
    );
};

export default RobotScene;
